root=pathlib.Path('/opt/quiz-master/releases')
assert root.resolve()==root and not root.is_symlink()
def digest(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def available():s=os.statvfs(root);return s.f_bavail*s.f_frsize
before=available();targets=[];logs=[]
for x,prov in zip(manifest['candidates'],manifest['provenance']):
 p=pathlib.Path(x['path']);assert prov['path']==str(p)
 assert p.parent.parent==root and p.parent.name==x['build']
 assert x['build'] not in manifest['protected_builds']
 assert p.resolve()==p and p.is_dir() and not p.is_symlink() and not p.parent.is_symlink()
 assert {f.name for f in p.iterdir()}=={'api.log','quiz.sqlite','rollback-api'}
 assert all(f.is_file() and not f.is_symlink() for f in p.iterdir())
 run=p.name.removeprefix('rehearsal-');result=p.parent/(run+'-rehearsal.json');src=p.parent/('rehearse-'+run+'.py')
 assert digest(result)==prov['result_sha256'] and digest(src)==prov['script_sha256']
 q=json.loads(result.read_text());assert q['migration']=='ok' and q['integrity']=='ok' and q['original_rows_preserved'] is True and q['old_api_rollback']=='ok'
 assert repr(p.name) in src.read_text() and '/opt/quiz-master/backups/'+run+'.sqlite' in src.read_text()
 dest=p.parent/(run+'-preserved-api.log');assert not dest.exists() and not dest.is_symlink()
 targets.append(p);logs.append((p/'api.log',dest,digest(p/'api.log')))
# Abort on any process using a target, including a file descriptor or cwd.
for proc in pathlib.Path('/proc').iterdir():
 if not proc.name.isdigit():continue
 try:links=[proc/'cwd',proc/'exe',*list((proc/'fd').iterdir())]
 except FileNotFoundError:continue
 for link in links:
  try:value=os.readlink(link).removesuffix(' (deleted)')
  except FileNotFoundError:continue
  assert not any(value==str(p) or value.startswith(str(p)+'/') for p in targets),('active rehearsal process',proc.name)
# Exact three-file sandboxes only: no recursive removal or wildcard deletion.
for p,(log,dest,h) in zip(targets,logs):
 log.rename(dest);assert digest(dest)==h
 (p/'quiz.sqlite').unlink();(p/'rollback-api').unlink();p.rmdir()
 assert not p.exists()
after=available()
print(json.dumps({'deleted_paths':[str(p) for p in targets],'preserved_logs':[{'path':str(dest),'sha256':h} for _,dest,h in logs],'available_bytes_before':before,'available_bytes_after':after,'available_bytes_delta':after-before},indent=2))
